   /* CdlseparatinglinesOpenAndFill anchored at startIdx — the composed-open fusion seam. */
   internal CdlseparatinglinesStream CdlseparatinglinesOpenAndFillInternal( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, int startIdx, out int outBegIdx, out int outNBElement, Span<int> outInteger )
   {
      CdlseparatinglinesStream sp = new CdlseparatinglinesStream(this);
      RetCode retCode = CdlseparatinglinesOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, out outBegIdx, out outNBElement, outInteger, 1);
      sp.outRangeBegIdx = outBegIdx;
      sp.outRangeCount = outNBElement;
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSEPARATINGLINES", "openAndFill", retCode);
   }

   /* Internal startIdx-anchored open behind CdlseparatinglinesOpen (composition seam). */
   internal CdlseparatinglinesStream CdlseparatinglinesOpenInternal( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, int startIdx )
   {
      CdlseparatinglinesStream sp = new CdlseparatinglinesStream(this);
      int[] sink_outInteger = new int[1];
      RetCode retCode = CdlseparatinglinesOpenImpl(sp, inOpen, inHigh, inLow, inClose, startIdx, out int outBegIdx, out int outNBElement, sink_outInteger, 0);
      sp.outRangeBegIdx = outBegIdx;
      sp.outRangeCount = outNBElement;
      if( retCode == RetCode.Success ) {
         return sp;
      }
      throw StreamFailure("CDLSEPARATINGLINES", "open", retCode);
   }

   /// <summary>Open a live <c>CDLSEPARATINGLINES</c> stream over the warm-up history.</summary>
   /// <remarks>
   /// <para>The handle's <see cref="CdlseparatinglinesStream.Value"/> starts at the
   /// last history bar's value — bit-identical to what <c>CDLSEPARATINGLINES</c>
   /// reports for that bar.</para>
   /// <para>The history must hold at least <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars (unstable-period aware). Nothing is written to any caller array; use
   /// <c>CdlseparatinglinesOpenAndFill</c> to get the warm-up values as well.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <returns>The open stream handle.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, or the input series
   /// have different lengths.</exception>
   /// <exception cref="System.ArgumentOutOfRangeException">The history is empty — which is what a null array becomes, since a span
   /// cannot be null — or it is longer than <see cref="Core.MAX_INDEX"/> + 1,
   /// the two index faults an opener can have (rules S1 and S2).</exception>
   public CdlseparatinglinesStream CdlseparatinglinesOpen( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose )
   {
      if( inOpen.IsEmpty ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSEPARATINGLINES open: history is empty", RetCode.OutOfRangeStartIndex);
      if( inOpen.Length > MAX_INDEX + 1 ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSEPARATINGLINES open: history is longer than MAX_INDEX + 1", RetCode.OutOfRangeEndIndex);
      if( inHigh.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES open: inHigh is empty", nameof(inHigh), RetCode.BadParam);
      if( inLow.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES open: inLow is empty", nameof(inLow), RetCode.BadParam);
      if( inClose.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES open: inClose is empty", nameof(inClose), RetCode.BadParam);
      RequireHistoryLength("CDLSEPARATINGLINES", "open", "inHigh", inHigh.Length, inOpen.Length);
      RequireHistoryLength("CDLSEPARATINGLINES", "open", "inLow", inLow.Length, inOpen.Length);
      RequireHistoryLength("CDLSEPARATINGLINES", "open", "inClose", inClose.Length, inOpen.Length);
      return CdlseparatinglinesOpenInternal(inOpen, inHigh, inLow, inClose, 0);
   }

   /// <summary><c>CdlseparatinglinesOpen</c> that also fills the output array(s) over the
   /// whole history in the same single pass.</summary>
   /// <remarks>
   /// <para>The values written are bit-identical to what <c>CDLSEPARATINGLINES</c>
   /// produces over the same series, so no separate batch call is needed for the
   /// warm-up plot.</para>
   /// <para>Output arrays must hold <c>historyLen -
   /// CDLSEPARATINGLINES_Lookback(...)</c> values and must not alias the inputs
   /// or each other — this path writes the outputs and then reads the input tail
   /// to seed its rings, so the batch tier's in-place allowance does not carry
   /// over here. Both are checked before anything is written, so an undersized
   /// span is an <c>ArgumentException</c> naming it rather than a fault from
   /// inside the fill.</para>
   /// <para>The range written is reported on the returned handle:
   /// <see cref="CdlseparatinglinesStream.OutRange"/>.</para>
   /// </remarks>
   /// <param name="inOpen">Open price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inHigh">High price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inLow">Low price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="inClose">Close price of each bar. The warm-up history, oldest bar first.</param>
   /// <param name="outInteger">+100 for a bullish (white second candle) hit, -100 for a bearish (black
   /// second candle) hit, 0 otherwise. Must hold at least <c>historyLen -
   /// CDLSEPARATINGLINES_Lookback(...)</c> values.</param>
   /// <returns>The open stream handle, with its fill range set.</returns>
   /// <exception cref="InsufficientHistoryException">The history holds fewer than <c>CDLSEPARATINGLINES_Lookback(...) + 1</c>
   /// bars.</exception>
   /// <exception cref="System.ArgumentException">An optional parameter is outside its documented range, the input series
   /// have different lengths, an output is shorter than the values the fill
   /// writes, or an output array aliases an input or another output.</exception>
   /// <exception cref="System.ArgumentOutOfRangeException">The history is empty — which is what a null array becomes, since a span
   /// cannot be null — or it is longer than <see cref="Core.MAX_INDEX"/> + 1,
   /// the two index faults an opener can have (rules S1 and S2).</exception>
   public CdlseparatinglinesStream CdlseparatinglinesOpenAndFill( ReadOnlySpan<double> inOpen, ReadOnlySpan<double> inHigh, ReadOnlySpan<double> inLow, ReadOnlySpan<double> inClose, Span<int> outInteger )
   {
      if( inOpen.IsEmpty ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSEPARATINGLINES openAndFill: history is empty", RetCode.OutOfRangeStartIndex);
      if( inOpen.Length > MAX_INDEX + 1 ) throw new TaLibArgumentOutOfRangeException(nameof(inOpen), "CDLSEPARATINGLINES openAndFill: history is longer than MAX_INDEX + 1", RetCode.OutOfRangeEndIndex);
      if( inHigh.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES openAndFill: inHigh is empty", nameof(inHigh), RetCode.BadParam);
      if( inLow.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES openAndFill: inLow is empty", nameof(inLow), RetCode.BadParam);
      if( inClose.IsEmpty ) throw new TaLibArgumentException("CDLSEPARATINGLINES openAndFill: inClose is empty", nameof(inClose), RetCode.BadParam);
      int guardOutLen = OpenFillCount("CDLSEPARATINGLINES", "openAndFill", inOpen.Length, CDLSEPARATINGLINES_Lookback());
      RequireHistoryLength("CDLSEPARATINGLINES", "openAndFill", "inHigh", inHigh.Length, inOpen.Length);
      RequireHistoryLength("CDLSEPARATINGLINES", "openAndFill", "inLow", inLow.Length, inOpen.Length);
      RequireHistoryLength("CDLSEPARATINGLINES", "openAndFill", "inClose", inClose.Length, inOpen.Length);
      RequireFillLength("CDLSEPARATINGLINES", "openAndFill", "outInteger", outInteger.Length, guardOutLen);
      return CdlseparatinglinesOpenAndFillInternal(inOpen, inHigh, inLow, inClose, 0, out _, out _, outInteger);
   }
